   !> Conductor-like PCM (gaussian charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs conductor_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_response(state, dv, hvp_v, error)
      !> State of conductor
      type(conductor_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call conductor_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, "[conductor_response] call conductor_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call conductor_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine conductor_response

   !> One direction of conductor_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_response_one(state, dv, hvp_v, error)
      !> State of conductor
      type(conductor_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[conductor_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[conductor_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s5
      tmp1 = 0.0_wp
      call state%solver%solve(state%op1, .false., dv, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%s1*tmp1
   end subroutine conductor_response_one

   !> Conductor-like PCM (gaussian charges): energy derivatives with respect to the solvent
   !> parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs conductor_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[out] grad_feps  partial derivative of the energy with respect to feps
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_param_weights(state, grad_feps, error)
      !> State of conductor
      type(conductor_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to feps
      real(wp), intent(out) :: grad_feps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp) :: tmp2

      if (state%matrix_free) then
         call conductor_mf_param_weights(state, grad_feps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, "[conductor_param_weights] call conductor_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_param_weights] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s5
      tmp1 = 0.5_wp*state%v
      tmp2 = dot(tmp1, state%s6)
      grad_feps = -tmp2
   end subroutine conductor_param_weights

   !> Conductor-like PCM (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs conductor_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] feps  dielectric factor of a conductor-like model, e.g. (eps - 1)/eps
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_medium(state, feps, error)
      !> State of conductor
      type(conductor_complex_state), target, intent(inout) :: state
      !> Dielectric factor of a conductor-like model, e.g. (eps - 1)/eps
      complex(wp), intent(in) :: feps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat

      if (state%matrix_free) then
         call conductor_complex_mf_medium(state, feps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[conductor_complex_medium] call conductor_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_s6)) deallocate (state%cx_s6)
      if (allocated(state%cx_s8)) deallocate (state%cx_s8)
      if (allocated(state%cx_s9)) deallocate (state%cx_s9)
      if (allocated(state%cx_s10)) deallocate (state%cx_s10)
      if (allocated(state%cx_s11)) deallocate (state%cx_s11)
      if (allocated(state%cx_s2)) deallocate (state%cx_s2)
      if (allocated(state%cx_s3)) deallocate (state%cx_s3)
      if (allocated(state%cx_s4)) deallocate (state%cx_s4)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s6(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s8(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s9(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s10(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s11(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_complex_medium] allocation failed")
         return
      end if
      state%cx_s6 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled

      state%op1%points => state%r
      state%op1%c1 => state%s5
      state%cx_feps = feps
      state%cx_s1 = -state%cx_feps

      state%cx_ready = 2
   end subroutine conductor_complex_medium

   !> Conductor-like PCM (gaussian charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs conductor_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_solve(state, v, energy, q, grad_v, error)
      !> State of conductor
      type(conductor_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp5(:), tmp6(:)
      complex(wp), allocatable :: tmp3(:), tmp4(:), tmp7(:), tmp8(:)
      complex(wp) :: tmp1, tmp2, tmp9

      if (state%matrix_free) then
         call conductor_complex_mf_solve(state, v, energy, q, grad_v, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[conductor_complex_solve] call conductor_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[conductor_complex_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[conductor_complex_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[conductor_complex_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_complex_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op1%points => state%r
      state%op1%c1 => state%s5
      state%cx_v = v
