   !> Conductor-like PCM (gaussian charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs conductor_complex_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_response(state, dv, hvp_v, error)
      !> State of conductor
      type(conductor_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call conductor_complex_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[conductor_complex_response] call conductor_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_complex_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_complex_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call conductor_complex_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine conductor_complex_response

   !> One direction of conductor_complex_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_response_one(state, dv, hvp_v, error)
      !> State of conductor
      type(conductor_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[conductor_complex_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[conductor_complex_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_complex_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s5
      tmp1 = 0.0_wp
      call state%solver%solve_complex(state%op1, .false., dv, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%cx_s1*tmp1
   end subroutine conductor_complex_response_one

   !> Conductor-like PCM (gaussian charges): energy derivatives with respect to the solvent
   !> parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs conductor_complex_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[out] grad_feps  partial derivative of the energy with respect to feps
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_param_weights(state, grad_feps, error)
      !> State of conductor
      type(conductor_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to feps
      complex(wp), intent(out) :: grad_feps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:)
      complex(wp) :: tmp2

      if (state%matrix_free) then
         call conductor_complex_mf_param_weights(state, grad_feps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[conductor_complex_param_weights] call conductor_complex_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_complex_param_weights] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s5
      tmp1 = 0.5_wp*state%cx_v
      tmp2 = sum(tmp1*state%cx_s6)
      grad_feps = -tmp2
   end subroutine conductor_complex_param_weights

   !> Conductor-like PCM (gaussian charges): build the cavity operators
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] r  positions of the surface points
   !> @param[in] xi  gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
   !> @param[in] F  switching function (1 where the grid is not switched)
   !> @param[out] error  error handling; allocated on failure
   !> @param[in] solver  linear solver, copied into the state; default dense LAPACK (Cholesky,
   !> symmetric or LU)
   subroutine conductor_mf_assemble(state, r, xi, F, error, solver)
      !> State of conductor
      type(conductor_state), target, intent(inout) :: state
      !> Positions of the surface points
      real(wp), contiguous, intent(in) :: r(:, :)
      !> Gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
      real(wp), contiguous, intent(in) :: xi(:)
      !> Switching function (1 where the grid is not switched)
      real(wp), contiguous, intent(in) :: F(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error
      !> Linear solver
      class(pcm_solver), intent(in), optional :: solver

      integer :: npt
      integer :: stat

      stat = 0
      npt = size(r, 2)
      if (npt < 1) then
         call fatal_error(error, "[conductor_mf_assemble] empty discretization")
         return
      end if
      if (any(shape(r) /= [3, npt])) then
         call fatal_error(error, "[conductor_mf_assemble] r: wrong shape")
         return
      end if
      if (any(shape(xi) /= [npt])) then
         call fatal_error(error, "[conductor_mf_assemble] xi: wrong shape")
         return
      end if
      if (any(shape(F) /= [npt])) then
         call fatal_error(error, "[conductor_mf_assemble] F: wrong shape")
         return
      end if
      state%ready = 0
      if (allocated(state%solver)) deallocate (state%solver)
      if (allocated(state%v)) deallocate (state%v)
      if (allocated(state%xi)) deallocate (state%xi)
      if (allocated(state%r)) deallocate (state%r)
      if (allocated(state%F)) deallocate (state%F)
      if (allocated(state%s6)) deallocate (state%s6)
      if (allocated(state%s2)) deallocate (state%s2)
      if (allocated(state%s3)) deallocate (state%s3)
      if (allocated(state%s4)) deallocate (state%s4)
      if (allocated(state%s8)) deallocate (state%s8)
      if (allocated(state%s9)) deallocate (state%s9)
      if (allocated(state%s10)) deallocate (state%s10)
      if (allocated(state%s11)) deallocate (state%s11)
      if (allocated(state%s5)) deallocate (state%s5)
      state%npt = npt
      if (present(solver)) then
         allocate (state%solver, source=solver, stat=stat)
      else
         allocate (pcm_dense_solver :: state%solver, stat=stat)
      end if
      if (stat == 0) allocate (state%v(npt), stat=stat)
      if (stat == 0) allocate (state%xi(npt), stat=stat)
      if (stat == 0) allocate (state%r(3, npt), stat=stat)
      if (stat == 0) allocate (state%F(npt), stat=stat)
      if (stat == 0) allocate (state%s6(npt), stat=stat)
      if (stat == 0) allocate (state%s2(npt), stat=stat)
      if (stat == 0) allocate (state%s3(npt), stat=stat)
      if (stat == 0) allocate (state%s4(npt), stat=stat)
      if (stat == 0) allocate (state%s8(npt), stat=stat)
      if (stat == 0) allocate (state%s9(npt), stat=stat)
      if (stat == 0) allocate (state%s10(npt), stat=stat)
      if (stat == 0) allocate (state%s11(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_mf_assemble] allocation failed")
         return
      end if
      state%s6 = 0.0_wp
      call state%solver%reset(conductor_n_operators)
      state%matrix_free = .true.

      state%xi = xi
      state%r = r
      state%F = F
      state%op2%npt = npt
      state%op2%npoint = npt
      state%op2%id = 2
      state%op2%points => state%r
      state%op2%symmetric = .true.
      state%op2%positive_definite = .true.
      state%op2%r => state%r
      state%op2%xi => state%xi
      state%op2%F => state%F
      call state%solver%setup(state%op2, error)
      if (allocated(error)) return

      state%ready = 1
      state%assembled = state%assembled + 1
   end subroutine conductor_mf_assemble

   !> Conductor-like PCM (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs conductor_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] feps  dielectric factor of a conductor-like model, e.g. (eps - 1)/eps
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_mf_medium(state, feps, error)
      !> State of conductor
      type(conductor_state), target, intent(inout) :: state
      !> Dielectric factor of a conductor-like model, e.g. (eps - 1)/eps
      real(wp), intent(in) :: feps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[conductor_mf_medium] call conductor_assemble first")
         return
      end if
      state%ready = 1

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%xi => state%xi
      state%op2%F => state%F
      state%feps = feps
      state%s1 = -state%feps

      state%ready = 2
   end subroutine conductor_mf_medium

   !> Conductor-like PCM (gaussian charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs conductor_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_mf_solve(state, v, energy, q, grad_v, error)
      !> State of conductor
      type(conductor_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      real(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      real(wp), intent(out) :: energy
      !> Apparent surface charges
      real(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp5(:), tmp9(:), tmp109(:), tmp110(:)
      real(wp) :: tmp1, tmp2, tmp6, tmp7, tmp8, tmp111
      real(wp), allocatable :: tmp10(:)
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, "[conductor_mf_solve] call conductor_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[conductor_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[conductor_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[conductor_mf_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp109(npt), stat=stat)
      if (stat == 0) allocate (tmp110(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_mf_solve] allocation failed")
         return
      end if
      state%ready = 2

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%xi => state%xi
      state%op2%F => state%F
      state%v = v
      call state%solver%solve(state%op2, .false., state%v, state%s6, error)
      if (allocated(error)) return
      q = state%s1*state%s6
      tmp1 = dot(state%v, q)
