         tmp3 = tmp2*state%s6
         do i = 1, npt
            tmp6 = 1.0_wp/state%F(i)
            tmp7 = state%xi(i)*tmp6
            tmp8 = 0.7978845608028654_wp*tmp7
            tmp5(i) = tmp8
         end do
         tmp9 = tmp5*state%s6
         tmp4 = tmp9
         !$omp parallel &
         !$omp& private(i, j, tmp10) &
         !$omp& shared(npt, state) &
         !$omp& reduction(+: tmp4) &
         !$omp& default(private)
         allocate (tmp10(npt))
         block
            real(wp) :: tmp11, tmp12, tmp13, tmp14, tmp15, tmp17, tmp18, tmp21, tmp25

            !$omp do schedule(static)
            do j = 1, npt
               tmp11 = state%xi(j)
               tmp12 = state%r(1, j)
               tmp13 = state%r(2, j)
               tmp14 = state%r(3, j)
               tmp15 = state%s6(j)
               tmp17 = tmp11**(2)
               tmp18 = -tmp12
               tmp21 = -tmp13
               tmp25 = -tmp14
               !$omp simd
               do i = 1, j - 1
                  block
                     real(wp) :: tmp16, tmp19, tmp20, tmp22, tmp23, tmp24, tmp26, tmp27, tmp28, &
                                 tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, &
                                 tmp38

                     tmp19 = state%r(1, i) + tmp18
                     tmp20 = tmp19**(2)
                     tmp22 = state%r(2, i) + tmp21
                     tmp23 = tmp22**(2)
                     tmp24 = tmp20 + tmp23
                     tmp26 = state%r(3, i) + tmp25
                     tmp27 = tmp26**(2)
                     tmp28 = tmp24 + tmp27
                     tmp29 = tmp17*tmp28
                     tmp30 = state%xi(i)**(2)
                     tmp31 = tmp29*tmp30
                     tmp32 = tmp30 + tmp17
                     tmp33 = (-81.0_wp)*tmp32
                     tmp34 = tmp31 + tmp33
                     tmp16 = 0.5_wp + sign(0.5_wp, tmp34)
                     tmp10(i) = tmp16
                     tmp35 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp34))
                     tmp36 = tmp28 + tmp35
                     tmp37 = 1.0_wp/sqrt(tmp36)
                     tmp38 = tmp15*tmp37
                     tmp4(i) = tmp4(i) + tmp38*tmp16
                  end block
               end do
               !$omp simd
