                  block
                     real(wp) :: tmp16, tmp19, tmp20, tmp22, tmp23, tmp24, tmp26, tmp27, tmp28, &
                                 tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, &
                                 tmp38

                     tmp19 = state%r(1, i) + tmp18
                     tmp20 = tmp19**(2)
                     tmp22 = state%r(2, i) + tmp21
                     tmp23 = tmp22**(2)
                     tmp24 = tmp20 + tmp23
                     tmp26 = state%r(3, i) + tmp25
                     tmp27 = tmp26**(2)
                     tmp28 = tmp24 + tmp27
                     tmp29 = tmp17*tmp28
                     tmp30 = state%xi(i)**(2)
                     tmp31 = tmp29*tmp30
                     tmp32 = tmp30 + tmp17
                     tmp33 = (-81.0_wp)*tmp32
                     tmp34 = tmp31 + tmp33
                     tmp16 = 0.5_wp + sign(0.5_wp, tmp34)
                     tmp10(i) = tmp16
                     tmp35 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp34))
                     tmp36 = tmp28 + tmp35
                     tmp37 = 1.0_wp/sqrt(tmp36)
                     tmp38 = tmp15*tmp37
                     tmp4(i) = tmp4(i) + tmp38*tmp16
                  end block
               end do
               do i = 1, npt
                  if (i == j) cycle
                  block
                     real(wp) :: tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46, tmp47, &
                                 tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, tmp56, &
                                 tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, tmp65, &
                                 tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, tmp74, &
                                 tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, tmp83, &
                                 tmp84, tmp85, tmp86, tmp87, tmp88, tmp89, tmp90, tmp91, tmp92, &
                                 tmp93, tmp94, tmp95, tmp96, tmp97, tmp98, tmp99, tmp100, tmp101, &
                                 tmp102, tmp103, tmp104, tmp105, tmp106, tmp107, tmp108

                     if (tmp10(i) < 0.5_wp) then
                        tmp39 = state%xi(i)**(2)
                        tmp40 = tmp39 + tmp17
                        tmp41 = 0.25_wp*tmp40
                        tmp42 = state%r(1, i) + tmp18
                        tmp43 = tmp42**(2)
                        tmp44 = state%r(2, i) + tmp21
                        tmp45 = tmp44**(2)
                        tmp46 = tmp43 + tmp45
                        tmp47 = state%r(3, i) + tmp25
                        tmp48 = tmp47**(2)
                        tmp49 = tmp46 + tmp48
                        tmp50 = tmp17*tmp49
                        tmp51 = tmp50*tmp39
                        tmp52 = -tmp51
                        tmp53 = tmp41 + tmp52
                        if (tmp53 >= 0.0_wp) then
                           tmp55 = 1.0_wp/sqrt(tmp40)
                           tmp56 = tmp55*state%xi(i)
                           tmp57 = tmp55**(2)
                           tmp58 = tmp50*tmp57
                           tmp59 = tmp58*tmp39
                           tmp60 = 9.422759064650411e-11_wp*tmp59
                           tmp61 = (-1.2290555301717926e-09_wp) + tmp60
                           tmp62 = tmp61*tmp17
                           tmp63 = tmp62*tmp49
                           tmp64 = tmp63*tmp57
                           tmp65 = tmp64*tmp39
                           tmp66 = 1.4807192815879218e-08_wp + tmp65
                           tmp67 = tmp50*tmp66
                           tmp68 = tmp67*tmp57
                           tmp69 = tmp68*tmp39
                           tmp70 = (-1.6365844691234924e-07_wp) + tmp69
                           tmp71 = tmp59*tmp70
                           tmp72 = 1.6462114365889246e-06_wp + tmp71
                           tmp73 = tmp50*tmp72
                           tmp74 = tmp73*tmp57
                           tmp75 = tmp74*tmp39
                           tmp76 = (-1.492565035840625e-05_wp) + tmp75
                           tmp77 = tmp50*tmp76
                           tmp78 = tmp77*tmp57
                           tmp79 = tmp78*tmp39
                           tmp80 = 0.00012055332981789664_wp + tmp79
                           tmp81 = tmp58*tmp80
                           tmp82 = tmp81*tmp39
                           tmp83 = (-0.0008548327023450852_wp) + tmp82
                           tmp84 = tmp50*tmp83
                           tmp85 = tmp84*tmp57
                           tmp86 = tmp85*tmp39
                           tmp87 = 0.005223977625442188_wp + tmp86
                           tmp88 = tmp59*tmp87
                           tmp89 = (-0.026866170645131252_wp) + tmp88
                           tmp90 = tmp50*tmp89
                           tmp91 = tmp90*tmp57
                           tmp92 = tmp91*tmp39
                           tmp93 = 0.11283791670955126_wp + tmp92
                           tmp94 = tmp59*tmp93
                           tmp95 = (-0.37612638903183754_wp) + tmp94
                           tmp96 = tmp50*tmp95
                           tmp97 = tmp96*tmp57
                           tmp98 = tmp97*tmp39
                           tmp99 = 1.1283791670955126_wp + tmp98
                           tmp100 = tmp56*tmp99
                           tmp54 = tmp100*tmp11
                        else
                           tmp101 = 1.0_wp/sqrt(tmp49)
                           tmp102 = 1.0_wp/sqrt(tmp40)
                           tmp103 = tmp102*state%xi(i)
                           tmp104 = sqrt(tmp49)
                           tmp105 = tmp103*tmp104
                           tmp106 = tmp105*tmp11
                           tmp107 = erf(tmp106)
                           tmp54 = tmp101*tmp107
                        end if
                        tmp108 = tmp54*tmp15
                        tmp4(i) = tmp4(i) + tmp108
                     end if
