               end do
            end do
            !$omp end do
         end block
         deallocate (tmp10)
         !$omp end parallel
         tmp109 = -tmp4
         tmp110 = state%v + tmp109
         tmp111 = dot(tmp3, tmp110)
         energy = energy + tmp111
      end if

      state%ready = 3
   end subroutine conductor_mf_solve

   !> Conductor-like PCM (gaussian charges): energy gradient with respect to the cavity inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs conductor_solve on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_xi  partial derivative of the energy with respect to xi
   !> @param[out] grad_F  partial derivative of the energy with respect to F
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_mf_weights(state, grad_r, grad_xi, grad_F, error)
      !> State of conductor
      type(conductor_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      real(wp), contiguous, intent(out) :: grad_r(:, :)
