      state%s8 = state%s7*state%s6
      state%s9 = state%s8*state%s6
      do i = 1, npt
         tmp1 = 1.0_wp/state%F(i)
         tmp2 = 0.7978845608028654_wp*tmp1
         state%s10(i) = tmp2
      end do
      do i = 1, npt
         tmp3 = state%F(i)**(-2)
         tmp4 = tmp3*state%xi(i)
