      end do
      tmp6 = 0.0_wp
      tmp7 = 0.0_wp
      tmp8 = 0.0_wp
      tmp9 = 0.0_wp
      tmp10 = 0.0_wp
      !$omp parallel &
      !$omp& private(i, j, tmp11) &
