            tmp137 = tmp19**(5)
            tmp141 = tmp19**(9)
            tmp155 = tmp19**(13)
            tmp159 = tmp19**(15)
            tmp171 = tmp19**(19)
            tmp178 = tmp19**(11)
            tmp183 = tmp19**(3)
            tmp191 = tmp19**(7)
            tmp195 = tmp19**(17)
            tmp250 = tmp19**(21)
            tmp12 = 0.0_wp
            tmp13 = 0.0_wp
            tmp14 = 0.0_wp
            tmp15 = 0.0_wp
            !$omp simd &
            !$omp& reduction(+: tmp12, tmp13, tmp14, tmp15)
            do i = 1, j - 1
               block
                  real(wp) :: tmp22, tmp25, tmp26, tmp28, tmp29, tmp30, tmp32, tmp33, tmp34, &
                              tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, &
                              tmp44, tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, &
                              tmp53, tmp54, tmp55, tmp56

                  tmp25 = state%s2(i) + tmp24
