                  tmp30 = tmp26 + tmp29
                  tmp32 = state%s4(i) + tmp31
                  tmp33 = tmp32**(2)
                  tmp34 = tmp30 + tmp33
                  tmp35 = tmp23*tmp34
                  tmp36 = state%xi(i)**(2)
                  tmp37 = tmp35*tmp36
                  tmp38 = tmp36 + tmp23
                  tmp39 = (-81.0_wp)*tmp38
                  tmp40 = tmp37 + tmp39
                  tmp22 = 0.5_wp + sign(0.5_wp, tmp40)
