                  tmp7(i) = tmp7(i) + tmp52*tmp22
                  tmp13 = tmp13 + tmp51*tmp22
                  tmp53 = tmp32*tmp44
                  tmp54 = tmp53*tmp16
                  tmp55 = tmp54*state%s8(i)
