                              tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, &
                              tmp44, tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, &
                              tmp53, tmp54, tmp55, tmp56

                  tmp25 = state%s2(i) + tmp24
                  tmp26 = tmp25**(2)
                  tmp28 = state%s3(i) + tmp27
                  tmp29 = tmp28**(2)
                  tmp30 = tmp26 + tmp29
                  tmp32 = state%s4(i) + tmp31
                  tmp33 = tmp32**(2)
                  tmp34 = tmp30 + tmp33
                  tmp35 = tmp23*tmp34
                  tmp36 = state%xi(i)**(2)
                  tmp37 = tmp35*tmp36
                  tmp38 = tmp36 + tmp23
                  tmp39 = (-81.0_wp)*tmp38
                  tmp40 = tmp37 + tmp39
                  tmp22 = 0.5_wp + sign(0.5_wp, tmp40)
                  tmp11(i) = tmp22
                  tmp41 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp40))
                  tmp42 = tmp34 + tmp41
                  tmp43 = 1.0_wp/sqrt(tmp42)
                  tmp44 = tmp43**(3)
                  tmp45 = tmp44*tmp16
                  tmp46 = tmp45*tmp25
                  tmp47 = tmp46*state%s8(i)
