                  tmp49 = tmp28*tmp44
                  tmp50 = tmp49*tmp16
                  tmp51 = tmp50*state%s8(i)
                  tmp52 = -tmp51
                  tmp7(i) = tmp7(i) + tmp52*tmp22
                  tmp13 = tmp13 + tmp51*tmp22
                  tmp53 = tmp32*tmp44
                  tmp54 = tmp53*tmp16
                  tmp55 = tmp54*state%s8(i)
                  tmp56 = -tmp55
                  tmp8(i) = tmp8(i) + tmp56*tmp22
                  tmp14 = tmp14 + tmp55*tmp22
               end block
            end do
            do i = 1, npt
               if (i == j) cycle
               block
                  real(wp) :: tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, tmp65, &
                              tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, tmp74, &
                              tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, tmp83, &
                              tmp85, tmp86, tmp87, tmp88, tmp89, tmp90, tmp91, tmp92, tmp93, &
                              tmp94, tmp95, tmp96, tmp97, tmp98, tmp99, tmp100, tmp101, tmp102, &
                              tmp103, tmp104, tmp105, tmp106, tmp107, tmp108, tmp109, tmp110, &
                              tmp111, tmp112, tmp113, tmp114, tmp115, tmp116, tmp117, tmp118, &
                              tmp119, tmp120, tmp121, tmp122, tmp123, tmp124, tmp125, tmp126, &
