   subroutine conductor_mf_tangent(state, dr, dxi, dF, dv, hvp_r, hvp_xi, hvp_F, hvp_v, error)
      !> State of conductor
      type(conductor_state), intent(inout) :: state
      !> Direction for r
      real(wp), contiguous, intent(in) :: dr(:, :, :)
      !> Direction for xi
      real(wp), contiguous, intent(in) :: dxi(:, :)
      !> Direction for F
      real(wp), contiguous, intent(in) :: dF(:, :)
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, r block
      real(wp), contiguous, intent(out) :: hvp_r(:, :, :)
      !> Hessian times direction, xi block
      real(wp), contiguous, intent(out) :: hvp_xi(:, :)
      !> Hessian times direction, F block
      real(wp), contiguous, intent(out) :: hvp_F(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%ready < 4) then
         call fatal_error(error, "[conductor_mf_tangent] call conductor_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[conductor_mf_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dxi) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_mf_tangent] dxi: wrong shape")
         return
      end if
      if (any(shape(dF) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_mf_tangent] dF: wrong shape")
         return
      end if
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_mf_tangent] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_r) /= [3, npt, nblk])) then
         call fatal_error(error, "[conductor_mf_tangent] hvp_r: wrong shape")
         return
      end if
      if (any(shape(hvp_xi) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_mf_tangent] hvp_xi: wrong shape")
         return
      end if
      if (any(shape(hvp_F) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_mf_tangent] hvp_F: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_mf_tangent] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call conductor_mf_tangent_one(state, dr(:, :, blk), dxi(:, blk), dF(:, blk), dv(:, blk), &
                                       hvp_r(:, :, blk), hvp_xi(:, blk), hvp_F(:, blk), &
                                       hvp_v(:, blk), error)
