                     tmp1748 = tmp1740 + tmp1747
                     tmp361 = tmp361 + tmp1748
                  end if
               end block
            end do
            tmp352(j) = tmp352(j) + tmp358
            tmp353(j) = tmp353(j) + tmp359
            tmp354(j) = tmp354(j) + tmp360
            tmp356(j) = tmp356(j) + tmp361
         end do
         !$omp end do
      end block
      deallocate (tmp357)
      !$omp end parallel
      hvp_r(1, :) = tmp352
      hvp_r(2, :) = tmp353
      hvp_r(3, :) = tmp354
      tmp1749 = tmp351*state%s6
      tmp1750 = state%s8*tmp350
      tmp1751 = tmp1749 + tmp1750
      tmp1752 = tmp1751*state%s10
      do i = 1, npt
         tmp1754 = state%F(i)**(-2)
         tmp1755 = dF(i)*tmp1754
         tmp1756 = (-0.7978845608028654_wp)*tmp1755
         tmp1753(i) = tmp1756
      end do
      tmp1757 = state%s9*tmp1753
      tmp1758 = tmp1752 + tmp1757
      tmp1759 = tmp355 + tmp1758
      hvp_xi = tmp1759 + tmp356
      tmp1760 = tmp1751*state%s11
      do i = 1, npt
         tmp1762 = dF(i)*state%xi(i)
         tmp1763 = state%F(i)**(-3)
         tmp1764 = tmp1762*tmp1763
         tmp1765 = (-2.0_wp)*tmp1764
         tmp1766 = state%F(i)**(-2)
         tmp1767 = dxi(i)*tmp1766
         tmp1768 = tmp1765 + tmp1767
         tmp1769 = (-0.7978845608028654_wp)*tmp1768
         tmp1761(i) = tmp1769
      end do
      tmp1770 = state%s9*tmp1761
      hvp_F = tmp1760 + tmp1770
      hvp_v = state%s1*tmp350
   end subroutine conductor_mf_tangent_one

   !> Conductor-like PCM (gaussian charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs conductor_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_mf_response(state, dv, hvp_v, error)
      !> State of conductor
      type(conductor_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%ready < 3) then
         call fatal_error(error, "[conductor_mf_response] call conductor_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_mf_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_mf_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call conductor_mf_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine conductor_mf_response

   !> One direction of conductor_mf_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_mf_response_one(state, dv, hvp_v, error)
      !> State of conductor
      type(conductor_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[conductor_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[conductor_mf_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_mf_response_one] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%xi => state%xi
      state%op2%F => state%F
      tmp1 = 0.0_wp
      call state%solver%solve(state%op2, .false., dv, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%s1*tmp1
   end subroutine conductor_mf_response_one

   !> Conductor-like PCM (gaussian charges): energy derivatives with respect to the solvent
   !> parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs conductor_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[out] grad_feps  partial derivative of the energy with respect to feps
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_mf_param_weights(state, grad_feps, error)
      !> State of conductor
      type(conductor_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to feps
      real(wp), intent(out) :: grad_feps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp) :: tmp2

      stat = 0
      npt = state%npt
      if (state%ready < 3) then
         call fatal_error(error, "[conductor_mf_param_weights] call conductor_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_mf_param_weights] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%xi => state%xi
      state%op2%F => state%F
      tmp1 = 0.5_wp*state%v
      tmp2 = dot(tmp1, state%s6)
      grad_feps = -tmp2
   end subroutine conductor_mf_param_weights

   !> Conductor-like PCM (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs conductor_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] feps  dielectric factor of a conductor-like model, e.g. (eps - 1)/eps
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_mf_medium(state, feps, error)
      !> State of conductor
      type(conductor_complex_state), target, intent(inout) :: state
      !> Dielectric factor of a conductor-like model, e.g. (eps - 1)/eps
      complex(wp), intent(in) :: feps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[conductor_complex_mf_medium] call conductor_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_s6)) deallocate (state%cx_s6)
      if (allocated(state%cx_s2)) deallocate (state%cx_s2)
      if (allocated(state%cx_s3)) deallocate (state%cx_s3)
      if (allocated(state%cx_s4)) deallocate (state%cx_s4)
      if (allocated(state%cx_s8)) deallocate (state%cx_s8)
      if (allocated(state%cx_s9)) deallocate (state%cx_s9)
      if (allocated(state%cx_s10)) deallocate (state%cx_s10)
      if (allocated(state%cx_s11)) deallocate (state%cx_s11)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s6(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s2(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s3(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s4(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s8(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s9(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s10(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s11(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_complex_mf_medium] allocation failed")
         return
      end if
      state%cx_s6 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%xi => state%xi
      state%op2%F => state%F
      state%cx_feps = feps
      state%cx_s1 = -state%cx_feps

      state%cx_ready = 2
   end subroutine conductor_complex_mf_medium

   !> Conductor-like PCM (gaussian charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs conductor_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_mf_solve(state, v, energy, q, grad_v, error)
      !> State of conductor
      type(conductor_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp5(:)
      real(wp) :: tmp6, tmp7, tmp8
      complex(wp), allocatable :: tmp3(:), tmp4(:), tmp9(:), tmp109(:), tmp110(:)
      complex(wp) :: tmp1, tmp2, tmp111
      real(wp), allocatable :: tmp10(:)
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[conductor_complex_mf_solve] call conductor_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[conductor_complex_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[conductor_complex_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[conductor_complex_mf_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp109(npt), stat=stat)
      if (stat == 0) allocate (tmp110(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_complex_mf_solve] allocation failed")
         return
      end if
      state%cx_ready = 2

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%xi => state%xi
      state%op2%F => state%F
      state%cx_v = v
      call state%solver%solve_complex(state%op2, .false., state%cx_v, state%cx_s6, error)
      if (allocated(error)) return
      q = state%cx_s1*state%cx_s6
      tmp1 = sum(state%cx_v*q)
      energy = 0.5_wp*tmp1
      grad_v = q
      if (state%solver%inexact()) then
         ! First-order correction for the residuals of the solves
         tmp2 = (-0.5_wp)*state%cx_feps
         tmp3 = tmp2*state%cx_s6
         do i = 1, npt
            tmp6 = 1.0_wp/state%F(i)
            tmp7 = state%xi(i)*tmp6
            tmp8 = 0.7978845608028654_wp*tmp7
            tmp5(i) = tmp8
         end do
         tmp9 = tmp5*state%cx_s6
         tmp4 = tmp9
         !$omp parallel &
         !$omp& private(i, j, tmp10) &
         !$omp& shared(npt, state) &
         !$omp& reduction(+: tmp4) &
         !$omp& default(private)
         allocate (tmp10(npt))
         block
            real(wp) :: tmp11, tmp12, tmp13, tmp14, tmp17, tmp18, tmp21, tmp25
            complex(wp) :: tmp15

            !$omp do schedule(static)
            do j = 1, npt
               tmp11 = state%xi(j)
               tmp12 = state%r(1, j)
               tmp13 = state%r(2, j)
               tmp14 = state%r(3, j)
               tmp15 = state%cx_s6(j)
               tmp17 = tmp11**(2)
               tmp18 = -tmp12
               tmp21 = -tmp13
               tmp25 = -tmp14
               !$omp simd
               do i = 1, j - 1
                  block
                     real(wp) :: tmp16, tmp19, tmp20, tmp22, tmp23, tmp24, tmp26, tmp27, tmp28, &
                                 tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37
                     complex(wp) :: tmp38

                     tmp19 = state%r(1, i) + tmp18
                     tmp20 = tmp19**(2)
                     tmp22 = state%r(2, i) + tmp21
                     tmp23 = tmp22**(2)
                     tmp24 = tmp20 + tmp23
                     tmp26 = state%r(3, i) + tmp25
                     tmp27 = tmp26**(2)
                     tmp28 = tmp24 + tmp27
                     tmp29 = tmp17*tmp28
                     tmp30 = state%xi(i)**(2)
                     tmp31 = tmp29*tmp30
                     tmp32 = tmp30 + tmp17
                     tmp33 = (-81.0_wp)*tmp32
                     tmp34 = tmp31 + tmp33
                     tmp16 = 0.5_wp + sign(0.5_wp, tmp34)
                     tmp10(i) = tmp16
                     tmp35 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp34))
                     tmp36 = tmp28 + tmp35
                     tmp37 = 1.0_wp/sqrt(tmp36)
                     tmp38 = tmp15*tmp37
                     tmp4(i) = tmp4(i) + tmp38*tmp16
                  end block
               end do
               !$omp simd
               do i = j + 1, npt
                  block
                     real(wp) :: tmp16, tmp19, tmp20, tmp22, tmp23, tmp24, tmp26, tmp27, tmp28, &
                                 tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37
                     complex(wp) :: tmp38

                     tmp19 = state%r(1, i) + tmp18
                     tmp20 = tmp19**(2)
                     tmp22 = state%r(2, i) + tmp21
                     tmp23 = tmp22**(2)
                     tmp24 = tmp20 + tmp23
                     tmp26 = state%r(3, i) + tmp25
                     tmp27 = tmp26**(2)
                     tmp28 = tmp24 + tmp27
                     tmp29 = tmp17*tmp28
                     tmp30 = state%xi(i)**(2)
                     tmp31 = tmp29*tmp30
                     tmp32 = tmp30 + tmp17
                     tmp33 = (-81.0_wp)*tmp32
                     tmp34 = tmp31 + tmp33
                     tmp16 = 0.5_wp + sign(0.5_wp, tmp34)
                     tmp10(i) = tmp16
                     tmp35 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp34))
                     tmp36 = tmp28 + tmp35
                     tmp37 = 1.0_wp/sqrt(tmp36)
                     tmp38 = tmp15*tmp37
                     tmp4(i) = tmp4(i) + tmp38*tmp16
                  end block
               end do
               do i = 1, npt
                  if (i == j) cycle
                  block
                     real(wp) :: tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46, tmp47, &
                                 tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, tmp56, &
                                 tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, tmp65, &
                                 tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, tmp74, &
                                 tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, tmp83, &
                                 tmp84, tmp85, tmp86, tmp87, tmp88, tmp89, tmp90, tmp91, tmp92, &
                                 tmp93, tmp94, tmp95, tmp96, tmp97, tmp98, tmp99, tmp100, tmp101, &
                                 tmp102, tmp103, tmp104, tmp105, tmp106, tmp107
                     complex(wp) :: tmp108

                     if (tmp10(i) < 0.5_wp) then
                        tmp39 = state%xi(i)**(2)
                        tmp40 = tmp39 + tmp17
                        tmp41 = 0.25_wp*tmp40
                        tmp42 = state%r(1, i) + tmp18
                        tmp43 = tmp42**(2)
                        tmp44 = state%r(2, i) + tmp21
                        tmp45 = tmp44**(2)
                        tmp46 = tmp43 + tmp45
                        tmp47 = state%r(3, i) + tmp25
                        tmp48 = tmp47**(2)
                        tmp49 = tmp46 + tmp48
                        tmp50 = tmp17*tmp49
                        tmp51 = tmp50*tmp39
                        tmp52 = -tmp51
                        tmp53 = tmp41 + tmp52
                        if (tmp53 >= 0.0_wp) then
                           tmp55 = 1.0_wp/sqrt(tmp40)
                           tmp56 = tmp55*state%xi(i)
                           tmp57 = tmp55**(2)
                           tmp58 = tmp50*tmp57
                           tmp59 = tmp58*tmp39
                           tmp60 = 9.422759064650411e-11_wp*tmp59
                           tmp61 = (-1.2290555301717926e-09_wp) + tmp60
                           tmp62 = tmp61*tmp17
                           tmp63 = tmp62*tmp49
                           tmp64 = tmp63*tmp57
                           tmp65 = tmp64*tmp39
                           tmp66 = 1.4807192815879218e-08_wp + tmp65
                           tmp67 = tmp50*tmp66
                           tmp68 = tmp67*tmp57
                           tmp69 = tmp68*tmp39
                           tmp70 = (-1.6365844691234924e-07_wp) + tmp69
                           tmp71 = tmp59*tmp70
                           tmp72 = 1.6462114365889246e-06_wp + tmp71
                           tmp73 = tmp50*tmp72
                           tmp74 = tmp73*tmp57
                           tmp75 = tmp74*tmp39
                           tmp76 = (-1.492565035840625e-05_wp) + tmp75
                           tmp77 = tmp50*tmp76
                           tmp78 = tmp77*tmp57
                           tmp79 = tmp78*tmp39
                           tmp80 = 0.00012055332981789664_wp + tmp79
                           tmp81 = tmp58*tmp80
                           tmp82 = tmp81*tmp39
                           tmp83 = (-0.0008548327023450852_wp) + tmp82
                           tmp84 = tmp50*tmp83
                           tmp85 = tmp84*tmp57
                           tmp86 = tmp85*tmp39
                           tmp87 = 0.005223977625442188_wp + tmp86
                           tmp88 = tmp59*tmp87
                           tmp89 = (-0.026866170645131252_wp) + tmp88
                           tmp90 = tmp50*tmp89
                           tmp91 = tmp90*tmp57
                           tmp92 = tmp91*tmp39
                           tmp93 = 0.11283791670955126_wp + tmp92
                           tmp94 = tmp59*tmp93
                           tmp95 = (-0.37612638903183754_wp) + tmp94
                           tmp96 = tmp50*tmp95
                           tmp97 = tmp96*tmp57
                           tmp98 = tmp97*tmp39
                           tmp99 = 1.1283791670955126_wp + tmp98
                           tmp100 = tmp56*tmp99
                           tmp54 = tmp100*tmp11
                        else
                           tmp101 = 1.0_wp/sqrt(tmp49)
                           tmp102 = 1.0_wp/sqrt(tmp40)
                           tmp103 = tmp102*state%xi(i)
                           tmp104 = sqrt(tmp49)
                           tmp105 = tmp103*tmp104
                           tmp106 = tmp105*tmp11
                           tmp107 = erf(tmp106)
                           tmp54 = tmp101*tmp107
                        end if
                        tmp108 = tmp54*tmp15
                        tmp4(i) = tmp4(i) + tmp108
                     end if
                  end block
               end do
            end do
            !$omp end do
         end block
         deallocate (tmp10)
         !$omp end parallel
         tmp109 = -tmp4
         tmp110 = state%cx_v + tmp109
         tmp111 = sum(tmp3*tmp110)
         energy = energy + tmp111
      end if

      state%cx_ready = 3
   end subroutine conductor_complex_mf_solve

   !> Conductor-like PCM (gaussian charges): energy gradient with respect to the cavity inputs
   !>
   !> - For the inputs of the last solve
   !> - Needs conductor_complex_solve on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[out] grad_r  partial derivative of the energy with respect to r
   !> @param[out] grad_xi  partial derivative of the energy with respect to xi
   !> @param[out] grad_F  partial derivative of the energy with respect to F
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_mf_weights(state, grad_r, grad_xi, grad_F, error)
      !> State of conductor
      type(conductor_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to r
      complex(wp), contiguous, intent(out) :: grad_r(:, :)
      !> Partial derivative of the energy with respect to xi
      complex(wp), contiguous, intent(out) :: grad_xi(:)
      !> Partial derivative of the energy with respect to F
      complex(wp), contiguous, intent(out) :: grad_F(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2, tmp3, tmp4, tmp5
      complex(wp), allocatable :: tmp6(:), tmp7(:), tmp8(:), tmp9(:), tmp10(:), tmp357(:), tmp358(:)
      real(wp), allocatable :: tmp11(:)
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[conductor_complex_mf_weights] call conductor_complex_solve first")
         return
      end if
      if (any(shape(grad_r) /= [3, npt])) then
         call fatal_error(error, "[conductor_complex_mf_weights] grad_r: wrong shape")
         return
      end if
      if (any(shape(grad_xi) /= [npt])) then
         call fatal_error(error, "[conductor_complex_mf_weights] grad_xi: wrong shape")
         return
      end if
      if (any(shape(grad_F) /= [npt])) then
         call fatal_error(error, "[conductor_complex_mf_weights] grad_F: wrong shape")
         return
      end if
      allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
