   !> Conductor-like PCM (gaussian charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs conductor_complex_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_mf_response(state, dv, hvp_v, error)
      !> State of conductor
      type(conductor_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[conductor_complex_mf_response] call conductor_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_complex_mf_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[conductor_complex_mf_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call conductor_complex_mf_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine conductor_complex_mf_response

   !> One direction of conductor_complex_mf_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_mf_response_one(state, dv, hvp_v, error)
      !> State of conductor
      type(conductor_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[conductor_complex_mf_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[conductor_complex_mf_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_complex_mf_response_one] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%xi => state%xi
      state%op2%F => state%F
      tmp1 = 0.0_wp
      call state%solver%solve_complex(state%op2, .false., dv, tmp1, error)
      if (allocated(error)) return
      hvp_v = state%cx_s1*tmp1
   end subroutine conductor_complex_mf_response_one

   !> Conductor-like PCM (gaussian charges): energy derivatives with respect to the solvent
   !> parameters
   !>
   !> - For the inputs of the last solve; independent of weights, which does not compute them
   !> - Needs conductor_complex_solve on the same state first
   !> - Keeps the state as it is; may be repeated in any order
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of conductor
   !> @param[out] grad_feps  partial derivative of the energy with respect to feps
   !> @param[out] error  error handling; allocated on failure
   subroutine conductor_complex_mf_param_weights(state, grad_feps, error)
      !> State of conductor
      type(conductor_complex_state), target, intent(inout) :: state
      !> Partial derivative of the energy with respect to feps
      complex(wp), intent(out) :: grad_feps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp), allocatable :: tmp1(:)
      complex(wp) :: tmp2

      stat = 0
      npt = state%npt
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, &
                          "[conductor_complex_mf_param_weights] call conductor_complex_solve first")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_complex_mf_param_weights] allocation failed")
         return
      end if

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%xi => state%xi
      state%op2%F => state%F
      tmp1 = 0.5_wp*state%cx_v
      tmp2 = sum(tmp1*state%cx_s6)
      grad_feps = -tmp2
   end subroutine conductor_complex_mf_param_weights

   !> Apply operator 1 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine conductor_op1_apply(self, trans, x, y)
      !> Operator
      class(conductor_op1), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         call gemv(self%c1, x, y, trans="t")
      else
         call gemv(self%c1, x, y)
      end if
   end subroutine conductor_op1_apply

   !> Form operator 1 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine conductor_op1_assemble(self, a, error)
      !> Operator
      class(conductor_op1), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      if (allocated(error)) return   ! nothing to allocate; error stays unset
      a = self%c1
   end subroutine conductor_op1_assemble

   !> Form operator 1 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine conductor_op1_assemble_block(self, idx, a, error)
      !> Operator
      class(conductor_op1), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:, :)

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[conductor_op1_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[conductor_op1_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%c1(idx, idx)
      a = tmp1
   end subroutine conductor_op1_assemble_block

   !> Apply operator 2 or its transpose
   !>
   !> @param[in]  self   operator
